(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*20+Math.cos(y*0.012-t*0.22)*14;
  const w1y = Math.cos(y*0.016-t*0.28)*18+Math.sin(x*0.014+t*0.32)*12;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025+t*0.5)*8+Math.cos(sy*0.02-t*0.4)*6;
  const w2y = Math.cos(sy*0.022-t*0.45)*7+Math.sin(sx*0.018+t*0.55)*5;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*110, 100+Math.cos(t*0.65+2)*65, 0.11, 2.1, 1.0],
    [400+Math.cos(t*0.55+1)*70, 140+Math.sin(t*0.75+4)*55, 0.065, 1.8, 0.85]
  ];
  let aS=0, iS=0, cS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS+=Math.cos(d*f*0.5-t*sp*0.4+0.8)*w*0.5;
  }
  const act=aS/8.2, inh=iS/8.2, cor=cS/8.2;
  const bg1=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2;
  const bg2=(Math.sin((fx+fy)*0.12+t*2.5)+Math.sin((fx-fy)*0.1-t*2))*0.2;
  const bg3=Math.sin(fx*0.07*t%1+fy*0.05)*Math.cos(fx*0.05-fy*0.08+t*0.6)*0.15;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy,fx-cx);
  const sp1=Math.sin(dist*0.05-ang*3-t*1.5), sp2=Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3=Math.sin(dist*0.03-ang*2+t*0.8)*0.5;
  const spiral=(sp1+sp2+sp3)*0.3;
  const vx=((fx%30)+30)%30, vy=((fy%30)+30)%30;
  const vor=(Math.min(vx,30-vx)+Math.min(vy,30-vy))/15;
  const vorF=Math.sin(vor*Math.PI*2-t*1.5)*0.2;
  const n1=Math.sin(fx*0.15)*Math.sin(fy*0.15);
  const n2=Math.sin((fx+fy)*0.1+t)*0.5;
  const n3=Math.sin(fx*0.08-t*0.7)*Math.cos(fy*0.12+t*0.5)*0.3;
  const cell=Math.tanh((n1+n2+n3)*1.5)*0.25;
  const rd1=Math.tanh((act-inh*0.65+bg*0.3+spiral)*2.2);
  const rd2=Math.tanh((act*0.8-inh*0.5+cor*0.4+vorF)*1.8);
  const blend=rd1*0.55+rd2*0.3+cell*0.15;
  const pulse=0.92+Math.sin(t*0.4)*0.08;
  const v=blend*0.5*pulse+0.5;
  const pal=[
    [6,12,52],[12,42,88],[18,78,118],[24,118,128],
    [60,148,118],[140,168,90],[198,178,62],[218,138,58],
    [198,88,62],[158,52,72],[98,28,68],[48,18,56],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.78+Math.sin(blend*Math.PI)*0.22;
  const edge=Math.abs(blend)>0.65?1.18:Math.abs(blend)>0.4?1.05:0.95;
  const shimmer=Math.sin(fx*0.3+fy*0.2+t*3)*0.04*Math.abs(blend);
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge*(1+shimmer))|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge*(1+shimmer))|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge*(1+shimmer))|0)
  ];
}
